class Solution:
    def clearDigits(self, s: str) -> str:
        result = []
        i = 0
        while i < len(s):
            if s[i].isdigit():
                # Find the first non-digit character to the left of the current digit
                j = i - 1
                while j >= 0 and s[j].isdigit():
                    j -= 1
                # If we found a non-digit character, remove it
                if j >= 0:
                    result.append(s[j])
                    # Continue from the character after the removed digit
                    i = j + 1
                else:
                    # No non-digit character to the left, so we can't remove anything
                    # This case should not happen given the problem constraints
                    break
            else:
                result.append(s[i])
                i += 1
        return "".join(result)
```

