class Solution:
    def losingPlayer(self, x: int, y: int) -> str:
        # The total value of all coins is x*75 + y*10.
        # We need to find the smallest value V such that V <= total_value.
        # If total_value - V is divisible by 115, then we can make V exactly.
        # Otherwise, we cannot reach V, so we lose.
        total_value = x * 75 + y * 10
        min_v = 0
        while total_value - min_v >= 115:
            min_v += 115
        if total_value - min_v < 115:
            return "Alice"
        else:
            return "Bob"
