        # Pad numbers with leading zeros to make them 4 digits
        def pad_to_4(digits: list[int]) -> str:
            return "0" * 4 + "".join(str(d) for d in digits)

        num1_padded = pad_to_4(list(str(num1)))
        num2_padded = pad_to_4(list(str(num2)))
