        for i in range(1, 4):
            # Take the smallest digit among the padded numbers for this position
            digit = min(key[i], key[i+1], key[i+2])
            # Pad the current digit with leading zeros if needed
            key[i] = "0" * 4 + str(digit)

        # Join the key digits back into a string and convert to integer
        return int("".join(key))
