class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        n = len(s)
        # Map each character to its cyclic distance from 'a'
        # a=0, b=1, ..., z=25
        char_to_dist = {c: (ord(c) - ord('a')) % 26 for c in 'abcdefghijklmnopqrstuvwxyz'}

        # Precompute the minimum distance between s[i] and s[j] for all pairs
        # This is needed for each position i in s to consider how many other positions j
        # can be chosen such that the total distance <= k.
        # Since we want the lexicographically smallest final string, we should process
        # positions from left to right (i=0 to n-1) and pick the best j for each i.

        min_dist = [float('inf')] * n

        for i in range(n):
            min_dist[i] = float('inf')
            for j in range(n):
                d = char_to_dist[s[i]] - char_to_dist[s[j]]
                if d <= k:
                    min_dist[i] = min(min_dist[i], d)

        # Now we iterate i from 0 to n-1. For each i, we want to find the smallest
        # non-negative integer d such that d <= k and d >= min_dist[i].
        # The smallest such d is max(0, min_dist[i] - k) if min_dist[i] <= k,
        # otherwise 0.

        result = []
        for i in range(n):
            if min_dist[i] <= k:
                d = max(0, min_dist[i] - k)
            else:
                d = 0
            result.append(chr(ord('a') + d))

        return ''.join(result)
