class Solution:
    def shortestSubstrings(self, arr: List[str]) -> List[str]:
        n = len(arr)
        if n == 0:
            return []

        # Build a frequency map for each string in arr
        # key: string, value: list of positions (indices) where it occurs
        pos_map = {}
        for i, s in enumerate(arr):
            if s not in pos_map:
                pos_map[s] = []
            pos_map[s].append(i)

        # Sort the positions within each string by their index
        for s in pos_map:
            pos_map[s].sort()

        # Precompute the set of all unique substrings that appear in any string in arr
        all_substrings = set()
        for s in arr:
            for i in range(len(s)):
                for j in range(i + 1, len(s)):
                    sub = s[i:j+1]
                    all_substrings.add(sub)

        # For each string in arr, find the shortest substring that does not appear in all_substrings
        # If no such substring exists, return empty string

        ans = []
        for i in range(n):
            s = arr[i]
            # Find the lexicographically smallest shortest substring not in all_substrings
            # We iterate from the end of the string (shortest possible) to the beginning
            # and keep track of the best (smallest) substring found so far

            best_sub = ""
            for j in range(len(s) - 1, -1, -1):
                sub = s[j:]
                if sub not in all_substrings:
                    if not best_sub or sub < best_sub:
                        best_sub = sub
            ans.append(best_sub)

        return ans
