    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7

        # dp[i][0] = number of stable arrays of length i ending with 0
        # dp[i][1] = number of stable arrays of length i ending with 1
        # We only care about lengths up to limit + 1 (since we need to check all subarrays of length > limit)
        dp = [[0] * (limit + 2) for _ in range(limit + 2)]

        # Initial state: length 1
        for i in range(limit + 2):
            dp[0][0] = 1
            dp[0][1] = 1

        # Transitions for length i -> i+1
        for i in range(2, limit + 2):
            for j in range(limit + 2):
                # If we end with 0:
                #   We need a 1 in the previous position (either at i-1 or at i-2)
                #   And the previous position must be stable (not full of 0s)
                if j == 0:
                    # dp[0][1] is 1 (only length 1, single 1)
                    dp[i][0] = (dp[i-1][1] + dp[i-2][1]) % MOD
                else:
                    # dp[i][0] = dp[i-1][0] + dp[i-2][0]
                    # But we must ensure the previous element is 1
                    # So: dp[i][0] = dp[i-1][0] + dp[i-2][0] if (i-1) != 0 and (i-2) != 0
                    if i - 1 != 0 and i - 2 != 0:
                        dp[i][0] = (dp[i-1][0] + dp[i-2][0]) % MOD
                    else:
                        dp[i][0] = 0

        # Transitions for length i -> i+1
        # If we end with 1:
        #   We need a 0 in the previous position (either at i-1 or at i-2)
        #   And the previous position must be stable (not full of 1s)
        for i in range(2, limit + 2):
            for j in range(limit + 2):
                if j == 0:
                    # dp[0][0] is 1 (only length 1, single 0)
                    dp[i][1] = (dp[i-1][0] + dp[i-2][0]) % MOD
                else:
                    # dp[i][1] = dp[i-1][1] + dp[i-2][1]
                    # But we must ensure the previous element is 0
