class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        # Build adjacency list for the graph
        adj = [[] for _ in range(n)]
        for i in range(n - 1):
            adj[i].append(i + 1)

        # Process each query
        result = []
        for u, v in queries:
            # If u is not reachable from 0, the distance is infinity
            if not self.find_shortest_path(0, n, v):
                result.append(float('inf'))
                continue

            # Update the shortest path distance
            min_dist = self.find_shortest_path(0, n, v)
            result.append(min_dist)

        return result

    def find_shortest_path(self, start: int, end: int, current: int) -> int:
        """
        Find the shortest path distance from 'start' to 'end' using BFS.
        Returns the minimum distance if reachable, otherwise infinity.
        """
        if current == end:
            return 0

        # BFS queue
        queue = collections.deque([current])
        visited = set([current])
        dist = {current: 0}

        while queue:
            u = queue.popleft()

            if u == end:
                return dist[u]

            for v in adj[u]:
                if v not in visited:
                    new_dist = dist[u] + 1
                    if new_dist < dist.get(v, float('inf')):
                        dist[v] = new_dist
                        visited.add(v)
                        queue.append(v)

        return float('inf')
