class Solution:
    def resultsArray(self, nums: List[int], k: int) -> List[int]:
        # Group consecutive identical elements into a single representative
        groups = {}
        current_group = []
        for i in range(len(nums)):
            if current_group:
                if nums[i] == current_group[-1]:
                    current_group.append(nums[i])
                else:
                    current_group.append(nums[i])
            else:
                current_group = [nums[i]]
        # Add the last group
        current_group.append(current_group[-1])
        # Convert to a list of unique values
        groups = list(set(current_group))

        # Calculate max element for each consecutive subarray of length k
        # Since we only have unique values, we can iterate over groups
        # and compute the max value for each consecutive group of length k
        max_values = []
        for i in range(len(groups) - k + 1):
            max_values.append(groups[i + k - 1])

        # Build result array
        result = []
        for i in range(len(nums) - k + 1):
            # Check if current subarray is consecutive (i.e., all elements in nums[i..i+k-1] are equal)
            if nums[i + k - 1] == nums[i] == nums[i + 1] == nums[i + 2]:
                result.append(max_values[i])
            else:
                result.append(-1)

        return result
