class Solution:
    def countPairs(self, nums: List[int]) -> int:
        # Group elements by their sorted version
        sorted_nums = {}
        for n in nums:
            s = sorted(n)
            if s not in sorted_nums:
                sorted_nums[s] = []
            sorted_nums[s].append(n)

        count = 0
        # For each unique sorted version, check how many pairs exist
        for s, sorted_list in sorted_nums.items():
            if len(sorted_list) < 2:
                continue

            n1, n2 = sorted_list[0], sorted_list[1]
            if n1 == n2:
                continue

            # Count pairs where we can swap to make them equal
            # We want to find pairs (i, j) with i < j such that:
            # either (nums[i] == nums[j]) OR (nums[i] + nums[j] == 2 * (n1 + n2))
            # because one element can be swapped to become the other.

            pairs = 0
            for i in range(len(sorted_list)):
                for j in range(i + 1, len(sorted_list)):
                    if sorted_list[i] == sorted_list[j]:
                        pairs += 1
                    elif sorted_list[i] + sorted_list[j] == 2 * (n1 + n2):
                        pairs += 1

            count += pairs

        return count
