                adj[i].append(j)
                adj[j].append(i)

        # Precompute distances between all pairs of cities (Dijkstra-like)
        # dist[i][j] = distance between city i and city j
        INF = float('inf')
        dist = [[INF] * n for _ in range(n)]

        def dijkstra(start, n):
            dist[start] = 0
            pq = [(0, start)]
            while pq:
                d, u = pq.pop()
                if d > dist[u]:
                    continue
                for v in adj[u]:
                    if dist[v] == INF or d + 1 < dist[v]:
                        dist[v] = d + 1
                        pq.append((d + 1, v))
            return dist

        dist = dijkstra(0, n)
        dist = dijkstra(n, n)

        # If k=0, return 0
        if k == 0:
            return 0

        # Precompute stayScore and travelScore for each city
        stay = [[0] * n for _ in range(n)]
        travel = [[0] * n for _ in range(n)]

