                travel[i][j] = travelScore[i][j]

        # DP approach
        # dp[i][j] = maximum points for a tourist starting at city i and visiting exactly j cities
        # We want to find dp[0][k]
        # Since n <= 200 and k <= 200, we can use a DP table of size n * n * k
        dp = [[0] * k for _ in range(n)]

