    s_counts = {}
    for char in s:
        s_counts[char] = s_counts.get(char, 0) + 1

    # Check if t can be formed by taking a subsequence of s
    # We need to find a subsequence of s that has the same characters as t,
    # but in the order they appear in t.

    # First, check if the character counts in t match the counts in s
    # (ignoring order for this check)
    if len(s_counts) != len(t_counts):
        return False

    # Create a mapping of character to index in s
    char_to_index = {}
    for i, char in enumerate(s):
        char_to_index[char] = i

    # Count occurrences of each character in t
    t_counts = {}
    for char in t:
        t_counts[char] = t_counts.get(char, 0) + 1

    # Build the subsequence indices
    subseq_indices = []
    for char in t:
        if char in char_to_index:
            subseq_indices.append(char_to_index[char])

    # Check if the subsequence indices are valid (not all same)
