from collections import Counter
import itertools

def solve():
    s = input()
    n = len(s)

    # Precompute the set of all possible length-3 palindromes
    # A string is a palindrome if it reads the same forwards and backwards.
    # Since we only care about the first 3 characters of s, we can generate them all.
    # However, generating all 27 combinations is O(1) anyway.
    all_palindromes = set()
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                p = s[i] + s[j] + s[k]
                all_palindromes.add(p)

    # Count triples (i, j, k) such that the concatenated string is a palindrome.
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (s[i] + s[j] + s[k]) in all_palindromes:
                    count += 1

    print(count)

